// 插件与统一约定（java-library/maven-publish/jacoco、发布与测试机制）由根 build.gradle.kts 的 subprojects 块授予
dependencies {
    api(libs.commons.lang3)
    // 本模块只消费 netty（util.internal/buffer/channel/http 编解码），codec-http 传递闭包恰好覆盖，不再全局背 reactor-netty 整栈
    api(libs.netty.codec.http)
    // 线程工厂签名上的 NonNull 注解仅编译期需要：compileOnly 供给，不入 POM 与运行时类路径
    compileOnly(libs.jspecify)
    api(libs.jakarta.validation.api)
    implementation(libs.hibernate.validator)
    implementation(libs.jakarta.el.api)
    implementation(libs.jakarta.el)

    // Gradle 9 不再自带 platform launcher；BOM 复用既有的 junit-jupiter 版本，不引入第二个版本号
    testImplementation(platform(libs.junit.bom))
    testImplementation(libs.junit.jupiter)
    testRuntimeOnly(libs.junit.platform.launcher)
    testRuntimeOnly(libs.logback.classic)
}

description = "turboweb-common"

// commons 覆盖率门禁分母：只统计支撑本次重构的公共面，exception/** 与 func/TirConsumer 不计入（spec §2.1）
val gateClasses = listOf(
    "top/turboweb/common/utils/thread/**",
    "top/turboweb/common/utils/resource/**",
    "top/turboweb/common/utils/base/**",
    "top/turboweb/common/limit/**",
    "top/turboweb/common/util/**"
)

tasks.named<org.gradle.testing.jacoco.tasks.JacocoCoverageVerification>("jacocoTestCoverageVerification") {
    dependsOn(tasks.named("test"))
    // classDirectories 是 Filterable：按 glob 收窄分母，报告仍展示全量类
    classDirectories.setFrom(classDirectories.files.map { dir -> fileTree(dir) { include(gateClasses) } })
    violationRules {
        rule {
            limit {
                counter = "LINE"
                minimum = "0.80".toBigDecimal()
            }
        }
    }
}
// 阶段 4 开闸（2026-10-07 终裁：commons 由"不接"改判"接 LINE ≥ 0.80"，spec §11.1 要求两模块皆启用）
tasks.named("check") {
    dependsOn(tasks.named("jacocoTestCoverageVerification"))
}

// PITest 变异作用域与覆盖率闸分母同形：由 gateClasses 列表推导，两处口径不分叉
configure<info.solidsoft.gradle.pitest.PitestPluginExtension> {
    targetClasses.set(gateClasses.map { it.removeSuffix("/**").replace('/', '.') + ".*" })
}
